CREATE TABLE IF NOT EXISTS ecosystem_certifications(id BIGSERIAL PRIMARY KEY,extension_key VARCHAR(190) NOT NULL,version VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','passed','failed','revoked')),score INTEGER NOT NULL DEFAULT 0 CHECK(score BETWEEN 0 AND 100),reviewer VARCHAR(120) NOT NULL DEFAULT 'automated',evidence_json TEXT NOT NULL DEFAULT '{}',started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(extension_key,version));
CREATE TABLE IF NOT EXISTS ecosystem_compatibility(extension_key VARCHAR(190) NOT NULL,version VARCHAR(64) NOT NULL,vazincms_constraint VARCHAR(64) NOT NULL,php_constraint VARCHAR(64) NOT NULL,db_drivers_json TEXT NOT NULL DEFAULT '[]',dependencies_json TEXT NOT NULL DEFAULT '{}',tested_matrix_json TEXT NOT NULL DEFAULT '{}',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(extension_key,version));
CREATE TABLE IF NOT EXISTS ecosystem_review_results(id BIGSERIAL PRIMARY KEY,extension_key VARCHAR(190) NOT NULL,version VARCHAR(64) NOT NULL,check_key VARCHAR(190) NOT NULL,status VARCHAR(20) NOT NULL CHECK(status IN('pass','fail','warn')),details TEXT NOT NULL DEFAULT '',evidence_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS ecosystem_api_registry(api_key VARCHAR(190) PRIMARY KEY,version VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'stable' CHECK(status IN('experimental','stable','deprecated','removed')),introduced_in VARCHAR(64) NOT NULL,deprecated_in VARCHAR(64),remove_in VARCHAR(64),notes TEXT NOT NULL DEFAULT '',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO schema_migrations(version) VALUES('10.27.0') ON CONFLICT(version) DO NOTHING;